import{_ as e,c as a,o as t,a4 as s}from"./chunks/framework.ttppV29E.js";const b=JSON.parse('{"title":"Basic Auth","description":"","frontmatter":{},"headers":[],"relativePath":"docs/endpoint-authentication/basic-auth.md","filePath":"docs/endpoint-authentication/basic-auth.md","lastUpdated":1791278387000}'),o={name:"docs/endpoint-authentication/basic-auth.md"},n=s('<h1 id="basic-auth" tabindex="-1">Basic Auth <a class="header-anchor" href="#basic-auth" aria-label="Permalink to &quot;Basic Auth&quot;">​</a></h1><p>Basic Auth allows you to set a username and password required to use the endpoint. Once set, the password will not be viewable again for security reasons.</p><p>Include the credentials in endpoint calls using the <code>Authorization</code> header with a Base64 encoded username and password separated by a single colon <code>:</code>.</p><p>For example, if you use <code>Aladdin</code> as the username and <code>open sesame</code> as the password, the header value is the Base64 encoding of <code>Aladdin:open sesame</code>, or <code>QWxhZGRpbjpvcGVuIHNlc2FtZQ==</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Basic QWxhZGRpbjpvcGVuIHNlc2FtZQ==</span></span></code></pre></div>',5),c=[n];function i(d,p,r,h,l,u){return t(),a("div",null,c)}const m=e(o,[["render",i]]);export{b as __pageData,m as default};
